CREATE TABLE `admins` (`id` text PRIMARY KEY NOT NULL, `email` text NOT NULL UNIQUE, `password_hash` text NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `profiles` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `title` text NOT NULL, `biography` text NOT NULL, `email` text NOT NULL, `phone` text, `location` text, `photo_key` text, `resume_key` text, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `skills` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `category` text NOT NULL, `proficiency` integer NOT NULL, `icon` text, `display_order` integer DEFAULT 0 NOT NULL, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `experiences` (`id` text PRIMARY KEY NOT NULL, `position` text NOT NULL, `organization` text NOT NULL, `employment_type` text, `description` text NOT NULL, `start_date` text NOT NULL, `end_date` text, `currently_working` integer DEFAULT false NOT NULL, `location` text, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `projects` (`id` text PRIMARY KEY NOT NULL, `title` text NOT NULL, `description` text NOT NULL, `image_key` text, `github_url` text, `live_url` text, `featured` integer DEFAULT false NOT NULL, `display_order` integer DEFAULT 0 NOT NULL, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `project_technologies` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES projects(id) ON DELETE CASCADE, `technology` text NOT NULL);
CREATE TABLE `education` (`id` text PRIMARY KEY NOT NULL, `institution` text NOT NULL, `degree` text NOT NULL, `field_of_study` text, `start_date` text, `end_date` text, `description` text, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `certificates` (`id` text PRIMARY KEY NOT NULL, `title` text NOT NULL, `issuer` text NOT NULL, `issue_date` text, `credential_url` text, `file_key` text, `description` text, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `social_links` (`id` text PRIMARY KEY NOT NULL, `platform` text NOT NULL, `url` text NOT NULL, `display_order` integer DEFAULT 0 NOT NULL, `published` integer DEFAULT true NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `contact_messages` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `email` text NOT NULL, `subject` text, `message` text NOT NULL, `read` integer DEFAULT false NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE INDEX `skills_order_idx` ON `skills` (`display_order`); CREATE INDEX `projects_order_idx` ON `projects` (`display_order`); CREATE INDEX `project_technologies_project_idx` ON `project_technologies` (`project_id`); CREATE INDEX `messages_created_idx` ON `contact_messages` (`created_at`);
